# --- титульник: правим текст, сохраняя оформление
def settext(p, text):
    r = p.runs; r[0].text = text
    for x in r[1:]: x.text = ""
settext(P[11], "ПО ЛАБОРАТОРНОЙ РАБОТЕ №5")
